const app=document.querySelector('#app'), queryInput=document.querySelector('#query');
let category='', voltages=new Set(), power='', query='', sort='', filterOpen=false, currentProduct=null;
function art(p,zoom=false){const n=p.accessory?3:4;return `<div class="product-visual ${zoom?'zoomed':''}" role="img" aria-label="AI-визуализация: ${p.name}"><div class="sprite ${p.accessory?'consumable-sprite':''}" style="background-position:${(p.image%n)*100/(n-1)}% ${Math.floor(p.image/n)*100/(n-1)}%"></div></div>`;}
function supply(p){return p.accessory?p.size:p.powerW?`${p.powerW} Вт`:`${p.voltage} В`;}
function card(p){return `<a class="card" href="#product/${p.id}"><div class="art">${p.badge?`<span class="badge">${p.badge}</span>`:''}${art(p)}<span class="watermark">KOPYTOV · BOLTERRA DEMO</span></div><div class="card-info"><span class="sku">${p.id} / ${p.power}</span><h2>${p.name}</h2><p class="spec">${supply(p)} · ${p.metric}</p><div class="card-bottom"><span>Подробнее</span><span class="arrow" aria-hidden="true">↗</span></div></div></a>`;}
function filtered(){const mass=p=>p.weight?Number(p.weight.replace(',','.')):Infinity;return catalogProducts.filter(p=>(!category||p.category===category)&&(!power||p.power===power)&&(!voltages.size||voltages.has(p.voltage))&&`${p.name} ${p.id}`.toLocaleLowerCase('ru').includes(query.trim().toLocaleLowerCase('ru'))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'ru'):sort==='weight'?(mass(a)===mass(b)?0:mass(a)-mass(b)):0);}
function updateResults(){const list=filtered();document.querySelector('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>Ничего не найдено</h2><p>Измените запрос или сбросьте фильтры.</p><button class="reset" data-reset>Сбросить поиск и фильтры</button></div>';document.querySelector('#count').textContent=`Показано ${list.length} из ${catalogProducts.length}`;document.querySelector('#toggle-filters').textContent=`☷ Фильтры${voltages.size||power?` · ${voltages.size+(power?1:0)}`:''}`;}
function catalog(){
 app.innerHTML=`<div class="crumb"><span>Главная</span><span>/</span><span>Каталог инструментов</span></div><section class="intro"><div><span class="eyebrow">BOLTERRA / ИНСТРУМЕНТ В ДЕТАЛЯХ</span><h1>От задачи — к инструменту.</h1><p>Сверление, шлифование или раскрой — выберите тип инструмента и сравните характеристики моделей.</p></div><div class="intro-note"><strong>Сетевой или аккумуляторный.</strong>25 демонстрационных товаров.<br>Инструменты, оснастка и расходные материалы.</div></section><div class="categories" role="group" aria-label="Категории">${['',...new Set(catalogProducts.map(p=>p.category))].map(c=>`<button class="chip" data-category="${c}" aria-pressed="${category===c}">${c||'Все товары'}</button>`).join('')}</div><button class="mobile-filter" id="toggle-filters" aria-expanded="${filterOpen}" aria-controls="filters">☷ Фильтры</button><div class="layout"><aside class="filters ${filterOpen?'open':''}" id="filters" aria-label="Фильтры каталога"><div class="filter-group"><fieldset><legend>Тип питания</legend>${[['','Любой'],['Аккумуляторный','Аккумулятор'],['Сетевой','От сети']].map(([v,n])=>`<label class="check"><input type="radio" name="power" value="${v}" ${power===v?'checked':''}>${n}</label>`).join('')}</fieldset></div><div class="filter-group"><fieldset><legend>Напряжение аккумулятора</legend>${[12,18,20].map(v=>`<label class="check"><input type="checkbox" name="voltage" value="${v}" ${voltages.has(v)?'checked':''}>${v} В</label>`).join('')}<p class="filter-hint">Этот фильтр исключает сетевые модели.</p></fieldset></div><div class="filter-group"><span class="eyebrow">ОБ ЭТОМ КАТАЛОГЕ</span><p class="filter-hint">Вымышленные модели и условные характеристики. Изображения созданы с AI. Товары не продаются.</p></div><button class="reset" data-reset>Сбросить всё</button></aside><section aria-label="Товары"><div class="toolbar"><span id="count" role="status" aria-live="polite"></span><label>Сортировка: <select id="sort" aria-label="Сортировка"><option value="">По умолчанию</option><option value="name">По названию</option><option value="weight">По массе</option></select></label></div><div class="grid" id="results"></div><div class="count-caption">BOLTERRA / 01 · Демонстрационный каталог · AI-визуализации</div></section></div>`;
 document.querySelector('#sort').value=sort;document.querySelectorAll('#filters .filter-group').forEach((g,i)=>{if(i<2)g.hidden=category==='Оснастка и расходники';});updateResults();
}
function detail(p){currentProduct=p;
 app.innerHTML=`<div class="crumb"><a href="#">Каталог</a><span>/</span><a href="#" data-return-category="${p.category}">${p.category}</a><span>/</span><span>${p.id}</span></div><div class="detail"><section aria-label="Изображения товара"><div class="art" id="main-art">${art(p)}<span class="watermark">KOPYTOV · BOLTERRA DEMO</span></div><div class="thumbs" role="group" aria-label="Масштаб изображения">${['Общий вид','Увеличенный фрагмент'].map((s,i)=>`<button data-view="${i}" aria-label="${s}" aria-pressed="${i===0}">${art(p,!!i)}</button>`).join('')}</div><p class="image-note">AI-визуализация вымышленной модели, не технический чертёж.</p></section><section><p class="eyebrow">${p.power} / ${p.id}</p><h1>${p.name}</h1><p class="description">${p.description||descriptions[p.image]}</p><div class="feature-row"><div><strong>${supply(p)}</strong><span>${p.accessory?p.sizeLabel:p.powerW?'Мощность':'Напряжение АКБ'}</span></div><div><strong>${p.metric}</strong><span>${p.metricLabel}</span></div><div><strong>${p.accessory?p.purpose:p.weight+' кг'}</strong><span>${p.accessory?'Назначение':p.powerW?'Масса':'Масса без АКБ'}</span></div></div><button class="primary" id="where-buy">Где купить ↗</button><p class="detail-note">Демонстрационная модель. Товар не продаётся.</p><a class="back" href="#">← Вернуться в каталог</a></section></div><div class="tabs" role="tablist" aria-label="Информация о товаре">${['Характеристики','Комплектация','Документы'].map((s,i)=>`<button role="tab" id="tab-${i}" data-tab="${i}" aria-controls="panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${s}</button>`).join('')}</div><section id="panel" class="tab-content" role="tabpanel" aria-labelledby="tab-0"></section>${relatedEquipment(p)}<section class="related"><p class="eyebrow">СРАВНИТЕ ДРУГИЕ МОДЕЛИ</p><h2>Также в каталоге</h2><div class="grid">${[...catalogProducts.filter(x=>x.id!==p.id&&x.category===p.category),...catalogProducts.filter(x=>x.category!==p.category)].slice(0,3).map(card).join('')}</div></section>`;tab(0);
}
function tab(i){const p=currentProduct;document.querySelectorAll('[data-tab]').forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1;});const panel=document.querySelector('#panel');panel.setAttribute('aria-labelledby',`tab-${i}`);
 const speedLabel=p.image===10?'Скорость ленты':[4,5].includes(p.image)?'Частота ударов':[8,11].includes(p.image)?'Частота колебаний':[12,13,15].includes(p.image)?'Частота хода':'Частота вращения';
 const rows=p.accessory?[['Артикул',p.id],['Тип изделия',p.power],[p.sizeLabel,p.size],[p.metricLabel,p.metric],...p.details]:[['Артикул',p.id],['Тип питания',p.power],[p.powerW?'Мощность':'Напряжение аккумулятора',supply(p)],[p.metricLabel,p.metric],[speedLabel,p.speed],[p.powerW?'Масса':'Масса без аккумулятора',`${p.weight} кг`]];
 panel.innerHTML=i===0?`<table><caption class="image-note">Условные данные для демонстрации интерфейса</caption><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th><td>${r[1]}</td></tr>`).join('')}</tbody></table>`:i===1?`<h2>Пример комплектации</h2><ul>${p.accessory?'<li>'+p.kit+'</li>':'<li>Инструмент — 1 шт.</li><li>'+(p.powerW?'Сетевой кабель предусмотрен конструкцией модели.':'Аккумулятор и зарядное устройство в условный комплект не входят.')+'</li>'}</ul><p>Оснастка на визуализации показана для пояснения типа инструмента. Это демонстрационные данные, а не предложение о продаже.</p>`:'<h2>Документы не добавлены</h2><p>Модель вымышленная. Инструкции, сертификаты и декларации для неё не выпускались.</p>';
}
function route(){let id=null;if(location.hash.startsWith('#product/')){try{id=decodeURIComponent(location.hash.slice(9));}catch{id='invalid';}}const p=catalogProducts.find(p=>p.id===id);if(p)detail(p);else{catalog();if(id)showInfo('Такой модели нет. Открыт полный каталог.');}queryInput.value=query;}
function showInfo(text){document.querySelector('#info-text').textContent=text;document.querySelector('#info').showModal();}
document.addEventListener('click',e=>{
 if(e.target.closest('.skip-link')){e.preventDefault();app.focus();app.scrollIntoView();return;}
 const link=e.target.closest('[data-return-category]');if(link){category=link.dataset.returnCategory;if(category==='Оснастка и расходники'){power='';voltages.clear();}}
 const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-category')){category=b.dataset.category;if(category==='Оснастка и расходники'){power='';voltages.clear();}catalog();}
 if(b.hasAttribute('data-reset')){query='';category='';voltages.clear();power='';sort='';queryInput.value='';catalog();}
 if(b.id==='toggle-filters'){filterOpen=!filterOpen;document.querySelector('#filters').classList.toggle('open',filterOpen);b.setAttribute('aria-expanded',String(filterOpen));}
 if(b.dataset.view!==undefined){document.querySelector('#main-art').innerHTML=art(currentProduct,b.dataset.view==='1')+'<span class="watermark">KOPYTOV · BOLTERRA DEMO</span>';document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}
 if(b.dataset.tab!==undefined)tab(+b.dataset.tab);
 if(b.id==='where-buy')showInfo('Это демонстрационный каталог. Модели BOLTERRA вымышлены; купить или заказать инструменты здесь нельзя.');
 if(b.id==='about')showInfo('Самостоятельный демонстрационный проект Дмитрия Копытова. Изображения созданы с AI, характеристики условные. Это не коммерческий заказ и не сайт производителя. Рабочее название BOLTERRA не проверено на регистрацию товарных знаков.');
 if(b.classList.contains('close')||b.classList.contains('close-info'))document.querySelector('#info').close();
});
document.addEventListener('change',e=>{if(e.target.matches('input[name="voltage"]')){const v=+e.target.value;e.target.checked?voltages.add(v):voltages.delete(v);updateResults();}if(e.target.matches('input[name="power"]')){power=e.target.value;updateResults();}if(e.target.id==='sort'){sort=e.target.value;updateResults();}});
queryInput.addEventListener('input',()=>{query=queryInput.value;if(location.hash.startsWith('#product/'))location.hash='';else updateResults();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();queryInput.focus();}if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=+e.target.dataset.tab;const i=e.key==='Home'?0:e.key==='End'?2:(n+(e.key==='ArrowRight'?1:2))%3;tab(i);document.querySelector(`#tab-${i}`).focus();}});
window.addEventListener('hashchange',()=>{const editing=document.activeElement===queryInput;route();if(!editing){const heading=app.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}window.scrollTo({top:0,behavior:'instant'});});route();
